-- =====================================================================
-- App Evolua — base de alimentos (por 100 g). Gerado por
-- ferramentas/gerar_base_alimentos.py — não editar à mão.
-- O app consulta esta base ANTES de chamar a IA; o que a IA descobrir de
-- novo é gravado aqui (fonte = 'ia') e fica disponível pra próxima vez.
-- Rodar no SQL Editor do Supabase. Pode rodar de novo: atualiza a base TACO
-- sem apagar o que a IA aprendeu.
-- =====================================================================
create table if not exists fit_alimentos (
  id bigint generated always as identity primary key,
  nome text not null unique,
  chaves text[] not null default '{}',
  kcal numeric not null,
  p numeric not null default 0,
  c numeric not null default 0,
  g numeric not null default 0,
  porcao numeric not null default 100,
  unidade text not null default 'porção',
  fonte text not null default 'taco',
  criado_por uuid default auth.uid(),
  criado_em timestamptz not null default now()
);

alter table fit_alimentos enable row level security;
drop policy if exists "ler alimentos" on fit_alimentos;
drop policy if exists "ia ensina alimento" on fit_alimentos;
create policy "ler alimentos" on fit_alimentos for select to anon, authenticated using (true);
-- usuários logados só podem ACRESCENTAR itens aprendidos pela IA (não alteram a base TACO)
create policy "ia ensina alimento" on fit_alimentos for insert to authenticated with check (fonte = 'ia');

on conflict (nome) do update set
  chaves = excluded.chaves, kcal = excluded.kcal, p = excluded.p, c = excluded.c, g = excluded.g,
  porcao = excluded.porcao, unidade = excluded.unidade, fonte = excluded.fonte;
